all, snapshot/large, and updates/large, preserving raw outputs.\\n\"\n(root/name).write_text(s)\nactions=json.loads((root/'actions.json').read_text())\nactions['actions'].append({'type':'write','path':name,'phase':'pre-probe decision criteria','sha256':hashlib.sha256(s.encode()).hexdigest()})\n(root/'actions.json').write_text(json.dumps(actions,indent=2)+'\\n')\nprint('Recorded recovery experiment decision criteria before execution.')\nPY",
